public static async Task<List<string>> GetPopularPostTitlesAsync(
    BlogContext context,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Views > 100
        orderby post.Views descending
        select post.Title;

    var titles = await query.ToListAsync(cancellationToken);
    return titles;
}
